import{_ as e,o as s,c as i,a2 as t}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"升级至 1.0.0-beta4","description":"","frontmatter":{},"headers":[],"relativePath":"zh/self-hosting/upgrade.md","filePath":"zh/self-hosting/upgrade.md","lastUpdated":1792570296000}'),p={name:"zh/self-hosting/upgrade.md"};function d(h,a,l,r,n,o){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="升级至-1-0-0-beta4" tabindex="-1">升级至 1.0.0-beta4 <a class="header-anchor" href="#升级至-1-0-0-beta4" aria-label="Permalink to &quot;升级至 1.0.0-beta4&quot;">​</a></h1><p>已在使用更早的 1.0 测试版？请<a href="#from-an-earlier-1-0-beta">直接原地升级</a>，无需迁移。</p><p>与 0.2 相比，1.0 系列是一次完整的架构重构，Python 运行时、前端、本地存储和集成都包含不兼容变更。用户数据有明确迁移路径；旧 Python 导入路径、内部 API 与旧前端接口不属于兼容承诺。本页其余部分说明如何把 0.2 安装升级至 1.0.0-beta4。</p><h2 id="_0-2-安装需要调整什么" tabindex="-1">0.2 安装需要调整什么 <a class="header-anchor" href="#_0-2-安装需要调整什么" aria-label="Permalink to &quot;0.2 安装需要调整什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>范围</th><th>从 0.2 升级的要求</th></tr></thead><tbody><tr><td>运行环境</td><td>使用 Python 3.12 或更新版本，在独立环境中安装</td></tr><tr><td>启动入口</td><td>使用 <code>paperseek serve</code> 及当前六命令 CLI，更新调用废弃命令的脚本</td></tr><tr><td>外部集成</td><td>客户端改用 <code>/api/v1</code>；需要 MCP 时安装同版本 <code>paperseek-mcp</code></td></tr><tr><td>配置</td><td>一次性转换仍有效的旧环境变量，检查忽略项，再将新名称加载到进程环境</td></tr><tr><td>存储</td><td>显式迁移 0.2 数据库；新 SQLite 结构变化由 Alembic 管理</td></tr><tr><td>运行中任务</td><td>切换前完成或取消旧任务，不假定旧版本的未完成任务或检查点可由新工作流继续执行</td></tr></tbody></table><p>新应用分离检索核心、任务服务和部署适配，保存的任务由 worker 租约、事件、检查点与产物共同管理。背景见<a href="./../changelog#v1-0-0-beta">更新日志</a>与<a href="./../developers/contributing#architecture">架构说明</a>。</p><p>本页适用于社区版本地安装。在线版用户不需要执行本地数据库迁移。</p><h2 id="升级前" tabindex="-1">升级前 <a class="header-anchor" href="#升级前" aria-label="Permalink to &quot;升级前&quot;">​</a></h2><ol><li>完成或取消活动任务，再停止旧应用与 worker。</li><li>将数据库、产物及配置备份到源码目录之外。</li><li>在独立环境中安装 1.0.0-beta4。</li><li>先验证迁移副本，再替换旧安装。</li></ol><p>确认保存的问题、结果数量和导出文件之前，请保留原备份。</p><h2 id="迁移-0-2-数据库" tabindex="-1">迁移 0.2 数据库 <a class="header-anchor" href="#迁移-0-2-数据库" aria-label="Permalink to &quot;迁移 0.2 数据库&quot;">​</a></h2><p>明确指定来源、目标和备份：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-v0.2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /backup/old-paperseek.db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --database</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/paperseek/paperseek.db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /backup/old-paperseek.v02.db</span></span></code></pre></div><p>不指定独立 <code>--database</code> 时，命令会以源路径为目标。演练时建议使用独立目标，便于检查。</p><p>阅读迁移报告，不要用尚未验证的输出替换原数据库。</p><h2 id="转换旧环境文件" tabindex="-1">转换旧环境文件 <a class="header-anchor" href="#转换旧环境文件" aria-label="Permalink to &quot;转换旧环境文件&quot;">​</a></h2><p>配置转换需要单独执行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --legacy-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /backup/old.env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/paperseek.env</span></span></code></pre></div><p>检查转换结果和被忽略的配置。生成的文件不会被 <code>paperseek serve</code> 自动加载，需要导出到进程环境，或交给服务管理器加载。</p><p>不要将 <code>--legacy-env</code> 与数据库迁移参数混用。真实 Key 和迁移报告均不应提交到 Git。</p><h2 id="验证新安装" tabindex="-1">验证新安装 <a class="header-anchor" href="#验证新安装" aria-label="Permalink to &quot;验证新安装&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --database</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/paperseek/paperseek.db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --database</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/paperseek/paperseek.db</span></span></code></pre></div><p>打开历史记录，检查一个旧任务并导出结果，再使用自己的提供方配置执行一次小规模新检索。</p><h2 id="from-an-earlier-1-0-beta" tabindex="-1">从更早的 1.0 测试版升级 <a class="header-anchor" href="#from-an-earlier-1-0-beta" aria-label="Permalink to &quot;从更早的 1.0 测试版升级 {#from-an-earlier-1-0-beta}&quot;">​</a></h2><p>1.0.0-beta4 沿用更早 1.0 测试版的数据库结构、配置和命令行，可以原地升级，无需迁移。</p><ol><li><p>完成或取消活动任务，停止服务及 worker，并备份数据库。</p></li><li><p>安装新版本：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;paperseek==1.0.0b4&quot;</span></span></code></pre></div><p>如使用 MCP 适配器，在同一条命令中加上 <code>&quot;paperseek-mcp==1.0.0b4&quot;</code>。使用 Docker 时，在 <code>.env</code> 中把 <code>PAPERSEEK_VERSION</code> 设为 <code>1.0.0-beta4</code>，再依次执行 <code>docker compose pull</code> 和 <code>docker compose up -d</code>。</p></li><li><p>启动服务，并用 <code>paperseek version</code> 确认版本。</p></li></ol><p>升级后最多同时运行 4 个检索和综述任务，可用 <code>PAPERSEEK_MAX_CONCURRENT_RUNS</code> 修改。如果你的网络需要代理才能访问模型或数据源，请在 <strong>设置 › 数据源 › 网络代理</strong> 中设置，或使用<a href="./../reference/configuration#网络代理">网络代理</a>中的环境变量。</p><p>尚未写出正文的综述，下次生成大纲时会重新提取证据，因此会再次调用写作模型；已有正文的综述保留原有证据。</p><p>随附的 <code>compose.yaml</code> 只向本机 127.0.0.1 发布端口。如需从其他设备访问，请使用新的 <code>compose.yaml</code>，在 <code>.env</code> 中设置 <code>PAPERSEEK_HOST=0.0.0.0</code>，并按<a href="./#network-access">网络访问</a>中的说明保护访问。</p><h2 id="回退" tabindex="-1">回退 <a class="header-anchor" href="#回退" aria-label="Permalink to &quot;回退&quot;">​</a></h2><p>先停止新进程，再恢复完整的升级前数据及相应旧运行环境。不要直接让旧程序打开已经向前迁移的数据库。</p>`,31)])])}const F=e(p,[["render",d]]);export{c as __pageData,F as default};
